#include <windows.h>
#include <stdio.h>
#include <stdlib.h>
int main(int argc,char**argv){HWND h=FindWindowW(L"ZimClipWindow",0);DWORD tid=GetWindowThreadProcessId(h,0);AttachThreadInput(GetCurrentThreadId(),tid,TRUE);int n=atoi(argv[1]);if(n==0){for(int id=1;id<=100;id++){if(id!=1&&id!=36&&id!=76&&id!=77&&id!=78)continue;HWND c=GetDlgItem(h,id);RECT r;GetWindowRect(c,&r);wchar_t t[512];GetWindowTextW(c,t,512);printf("id=%d visible=%d rect=%ld,%ld %ldx%ld text=",id,IsWindowVisible(c),r.left,r.top,r.right-r.left,r.bottom-r.top);printf("%ls\n",t);}}else if(n==1){HWND c=GetDlgItem(h,77);SetForegroundWindow(h);SetFocus(c);SendMessageW(c,CB_SHOWDROPDOWN,1,0);keybd_event(VK_DOWN,0,0,0);keybd_event(VK_DOWN,0,KEYEVENTF_KEYUP,0);keybd_event(VK_RETURN,0,0,0);keybd_event(VK_RETURN,0,KEYEVENTF_KEYUP,0);Sleep(300);printf("combo selected=%lld dropped=%lld\n",(long long)SendMessageW(c,CB_GETCURSEL,0,0),(long long)SendMessageW(c,CB_GETDROPPEDSTATE,0,0));}else if(n==2){HWND c=GetDlgItem(h,76);SetForegroundWindow(h);SetFocus(c);keybd_event('A',0,0,0);keybd_event('A',0,KEYEVENTF_KEYUP,0);Sleep(250);wchar_t t[100];GetWindowTextW(c,t,100);printf("search=%ls\n",t);}return 0;}
